Please read this section carefully because it contains additional provisions applicable only to our United States and Canada users. If you are a demo_app user located in the United States or Canada, you and we agree to submit all disputes to binding individual arbitration, except for those that involve intellectual property disputes and except those that can be brought in small claims court. This means you waive your right to have such disputes resolved in court by a judge or jury. Finally, you may bring a claim only on your behalf, and not on behalf of any official or other person, or class of people. You waive your right to participate in or have your dispute heard and resolved as, a class action, a class arbitration, or a representative action.

“excluded dispute” means any dispute relating to the enforcement or infringement of your or our intellectual property rights (such as copyrights, trademarks, domains, logos, trade dress, trade secrets, and patents) or efforts to interfere with our services or engage with our services in unauthorized ways (for example, automated ways). For clarity and notwithstanding the foregoing, those disputes relating to, arising out of, or in any way in connection with your rights of privacy and publicity are not excluded disputes.

Federal arbitration act: The United States federal arbitration act governs the interpretation and enforcement of this “special arbitration provision for United States or Canada users” section, including any question whether a dispute between demo_app and you are subject to arbitration.

Agreement to arbitrate for demo_app users located in the United States or Canada: for demo_app users who live in the United States or Canada, demo_app and you each agree to waive the right to a trial by judge or jury for all disputes, except for the excluded disputes. demo_app and you agree that all disputes (except for the excluded disputes), including those relating to, arising out of, or in any way in connection with your rights of privacy and publicity, will be resolved through final and binding arbitration. demo_app and you agree not to combine a dispute that is subject to arbitration under our terms with a dispute that is not eligible for arbitration under our terms. Before you commence arbitration of a dispute, you must provide us with a written notice of dispute that includes your (a) name; (b) residence address; (c) username; (d) email address or phone number you use for your demo_app account; (e) a detailed description of the dispute; and (f) the relief you seek. Any notice of dispute you send to us should be emailed to support@demo_app.com. Before we commence an arbitration, we will send you a notice of the dispute to the email address you provide, or other appropriate means. If we are unable to resolve a dispute within sixty (90) days after the notice of dispute is received, you or we may commence arbitration.

The arbitration will be administered by the American Arbitration Association (“AAA”) under its commercial arbitration rules in effect at the time the arbitration is started, including the optional rules for emergency measures of protection and the supplementary procedures for consumer-related disputes (together, the “AAA rules”). The arbitration will be presided over by a single arbitrator selected in accordance with the AAA rules. The AAA rules, information regarding initiating a dispute, and a description of the arbitration process are available at www.adr.org. Issues relating to the scope and enforceability of the arbitration provision are for a court to decide. The location of the arbitration and the allocation of fees and costs for such arbitration shall be determined in accordance with the AAA rules.

Opt-out procedure: you may opt-out of this agreement to arbitrate. If you do so, neither we nor you can require the other to participate in an arbitration proceeding. To opt-out, you must notify us in writing postmarked within 60 days of the later of: (a) the date that you first accepted our terms; and (b) the date you became subject to this arbitration provision. You must use this email address to opt-out: support@demo_app.com

You must include: (i) your name and residence address; (ii) the mobile phone number associated with your account; and (iii) a clear statement that you want to opt-out of our terms’ agreement to arbitrate. Small claims court. As an alternative to arbitration, if permitted by your local “small claims” court’s rules, you may bring your dispute in your local “small claims” court, as long as the matter advances on an individual (non-class) basis.

No class actions, class arbitrations, or representative actions for users located in the United States or Canada: we and you each agree that if you are a demo_app user located in the United States or Canada, each of us and you may bring disputes against the other only on its or your behalf, and not on behalf of any other person or entity, or any class of people. We and you each agree not to participate in a class action, a class-wide arbitration, disputes brought in a private attorney general or representative capacity, or consolidated disputes involving any other person or entity in connection with any dispute. If there is a final judicial determination that any particular dispute (or a request for particular relief) cannot be arbitrated in accordance with this provision's limitations, then only that dispute (or only that request for relief) may be brought in court. All other disputes (or requests for relief) remain subject to this provision. Place to file permitted court actions. If you opt-out of the agreement to arbitrate, if your dispute is an excluded dispute, or if the arbitration agreement is found to be unenforceable, you agree to be subject to the applicable provision in the “dispute resolution” section set forth above.
