          'Thank you for participating in our event. We hope you had as much fun attending as we did organizing it.We want to hear your feedback so we can keep improving our logistics and content. Please fill this quick survey and let us know your thoughts (your answers will be anonymous).eep improving our logistics and content. Please fill this quick survey and let us know your thoughts (your answers will be anonymous).':
              'شكرًا لك على المشاركة في حدثنا. نأمل أنك استمتعت بالحضور بنفس قدر ما استمتعنا بتنظيمه. نحن نرغب في سماع آرائك حتى نتمكن من تحسين خدماتنا ومحتوانا. يرجى ملء هذا الاستبيان السريع وإخبارنا بأفكارك (إجاباتك ستكون مجهولة).',

