              "عملك سوف يملأ جزءًا كبيرًا من حياتك، والطريقة الوحيدة للشعور بالرضا الحقيقي هي القيام بما تعتقد أنه عمل رائع.",
          "The only limit to our realization of tomorrow is our doubts of today.":
              "الحد الوحيد لتحقيق غدنا هو شكوكنا اليوم.",
          "Don’t be afraid to give up the good to go for the great.":
              "لا تخف من التخلي عن الجيد لتحقيق العظيم.",
          "The way to get started is to quit talking and begin doing.":
              "الطريقة للبدء هي التوقف عن الكلام والبدء في العمل.",
          "What you do today can improve all your tomorrows.":
              "ما تفعله اليوم يمكن أن يحسن جميع غدك.",
          "Don’t count the days, make the days count.":
              "لا تعد الأيام، اجعل الأيام تعد.",
          "Act as if what you do makes a difference. It does.":
              "تصرف كما لو أن ما تفعله يصنع فرقًا. إنه كذلك بالفعل.",
          "Quality means doing it right when no one is looking.":
              "الجودة تعني القيام بالشيء الصحيح عندما لا ينظر أحد.",
          "The only way to achieve the impossible is to believe it is possible.":
              "الطريقة الوحيدة لتحقيق المستحيل هي الإيمان بأنه ممكن.",
          "If you want to lift yourself up, lift up someone else.":
              "إذا كنت تريد أن ترفع نفسك، فارفع شخصًا آخر.",
          "Keep your eyes on the stars, and your feet on the ground.":
              "حافظ على عينيك على النجوم وقدميك على الأرض.",
          "Perfection is not attainable, but if we chase perfection we can catch excellence.":
              "الكمال غير قابل للتحقيق، لكن إذا سعينا للكمال يمكننا أن نصل إلى التميز.",
          "The difference between ordinary and extraordinary is that little extra.":
              "الفرق بين العادي والاستثنائي هو ذلك القليل الإضافي.",
          "It's not whether you get knocked down, it's whether you get up.":
              "الأمر لا يتعلق بما إذا كنت تتعرض للسقوط، بل يتعلق بما إذا كنت ستنهض.",
          "The secret of getting ahead is getting started.":
              "سر التقدم هو البدء.",
          "The best preparation for tomorrow is doing your best today.":
              "أفضل استعداد للغد هو القيام بأفضل ما يمكنك اليوم.",
          "Dream big and dare to fail.": "احلم بشكل كبير وجرؤ على الفشل.",
          "Success is a journey, not a destination.":
              "النجاح هو رحلة، وليس وجهة.",
          "What lies behind us and what lies before us are tiny matters compared to what lies within us.":
              "ما يكمن خلفنا وما يكمن أمامنا أمور صغيرة مقارنة بما يكمن داخلنا.",
          "Success seems to be connected with action. Successful people keep moving.":
              "يبدو أن النجاح مرتبط بالفعل. الأشخاص الناجحون يستمرون في التحرك.",
          "You are never too old to set another goal or to dream a new dream.":
              "أنت لا تكون أبدًا كبيرًا في السن لتحديد هدف آخر أو لحلم جديد.",
          "You Can't View This Request Details": 'لا يمكنك عرض تفاصيل الطلب',
          "The difference between who you are and who you want to be is what you do.":
              "الفرق بين من أنت ومن تريد أن تكون هو ما تفعله.",
          "Be the change that you wish to see in the world.":
              "كن التغيير الذي تتمنى رؤيته في العالم.",
          "If you can dream it, you can achieve it.":
              "إذا كان بإمكانك أن تحلم به، يمكنك تحقيقه.",
          "Aim for the moon. If you miss, you may hit a star.":
              "استهدف القمر. إذا فاتك، قد تصيب نجمة.",
          "The best way to find yourself is to lose yourself in the service of others.":
              "أفضل طريقة لتجد نفسك هي أن تفقد نفسك في خدمة الآخرين.",
          "The more you praise and celebrate your life, the more there is in life to celebrate.":
              "كلما زادت مدحك واحتفالك بحياتك، زادت الأشياء التي تحتفل بها في الحياة.",
          "There are no shortcuts to any place worth going.":
              "لا توجد طرق مختصرة إلى أي مكان يستحق الذهاب إليه.",
          "Challenges are what make life interesting and overcoming them is what makes life meaningful.":
              "التحديات هي ما تجعل الحياة ممتعة وتجاوزها هو ما يجعل الحياة ذات معنى.",
          "Do what you can with all you have, wherever you are.":
              "افعل ما تستطيع بكل ما لديك، أينما كنت.",
          "To accomplish great things, we must not only act, but also dream; not only plan, but also believe.":
              "لتحقيق أمور عظيمة، يجب علينا ليس فقط أن نعمل، بل أن نحلم؛ ليس فقط أن نخطط، بل أن نؤمن أيضًا.",
          "Your attitude, not your aptitude, will determine your altitude.":
              "موقفك، وليس مقدرتك، هو ما سيحدد مدى ارتفاعك.",
          "Success is not final, failure is not fatal: it is the courage to continue that counts.":
              "النجاح ليس نهائيًا، الفشل ليس قاتلاً: ما يهم هو الشجاعة للاستمرار.",
          "The purpose of life is not to be happy. It is to be useful, to be honorable, to be compassionate, to have it make some difference that you have lived and lived well.":
              "الغرض من الحياة ليس أن تكون سعيدًا. إنه أن تكون مفيدًا، وأن تكون محترمًا، وأن تكون رحيمًا، وأن تصنع فرقًا لأنك عشت وعشت جيدًا.",
          "Happiness is not something ready made. It comes from your own actions.":
              "السعادة ليست شيئًا جاهزًا. إنها تأتي من أفعالك الخاصة.",
          "Do what you can, with what you have, where you are.":
              "افعل ما تستطيع، بما لديك، حيثما كنت.",
          "What we think, we become.": "ما نفكر فيه، نصبحه.",
          "Your time is limited, don't waste it living someone else's life.":
              "وقتك محدود، لا تضيعه في عيش حياة شخص آخر.",
          "What we achieve inwardly will change outer reality.":
              "ما نحققه داخليًا سيغير الواقع الخارجي.",
          "The biggest risk is not taking any risk.":
              "أكبر مخاطرة هي عدم أخذ أي مخاطرة.",
          "In the end, we only regret the chances we didn't take.":
              "في النهاية، نحن نندم فقط على الفرص التي لم نغتنمها.",
          "To succeed in life, you need two things: ignorance and confidence.":
              "للنجاح في الحياة، تحتاج إلى شيئين: الجهل والثقة.",
          "Don't be pushed around by the fears in your mind. Be led by the dreams in your heart.":
              "لا تدع المخاوف في عقلك تدفعك. دع الأحلام في قلبك تقودك.",
          "The harder you work for something, the greater you'll feel when you achieve it.":
              "كلما عملت بجد من أجل شيء، كلما شعرت بعظمة أكبر عندما تحققه.",
          "Don't wait for opportunity. Create it.": "لا تنتظر الفرصة. اصنعها.",
          "Success doesn't just find you. You have to go out and get it.":
              "النجاح لا يجدك فقط. يجب عليك أن تخرج وتحصل عليه.",
          "Believe in yourself and all that you are. Know that there is something inside you that is greater than any obstacle.":
              "آمن بنفسك وكل ما أنت عليه. اعلم أن هناك شيئًا بداخلك أعظم من أي عقبة.",
          "Motivation is what gets you started. Habit is what keeps you going.":
              "الدافع هو ما يجعلك تبدأ. العادة هي ما تبقيك مستمرًا.",
          "Don't limit your challenges. Challenge your limits.":
              "لا تحد من تحدياتك. تحدى حدودك.",
          "It does not matter how slowly you go as long as you do not stop.":
              "لا يهم مدى بطء تقدمك طالما أنك لا تتوقف.",
          "Fall seven times, stand up eight.":
              "اسقط سبع مرات، انهض ثماني مرات.",
          "We generate fears while we sit. We overcome them by action.":
              "نحن نولد المخاوف أثناء الجلوس. نتغلب عليها بالفعل.",
          "You don’t have to be great to start, but you have to start to be great.":
              "لست بحاجة لأن تكون عظيمًا للبدء، ولكن يجب أن تبدأ لتصبح عظيمًا.",
          "Success is the sum of small efforts, repeated day in and day out.":
              "النجاح هو مجموع الجهود الصغيرة، المتكررة يومًا بعد يوم.",
          "If you're going through hell, keep going.":
              "إذا كنت تمر بالجحيم، استمر في السير.",
          "Action is the foundational key to all success.":
              "الفعل هو المفتاح الأساسي لكل نجاح.",
