          "Dr. Henry Link": "الدكتور هنري لينك",
          "Robert Collier": "روبرت كولير",
          "Pablo Picasso": "بابلو بيكاسو",
          'Create To Do': 'إنشاء مهمة',
          'Add User': 'إضافة مستخدم',
          'System Management': 'إدارة النظام',
          'Quick Actions': 'إجراءات سريعة',
          'Change Theme': 'تغيير المظهر',
          'general': 'عام',
          'Create Role': 'إنشاء دور',
          'Deactivate Account': 'تعطيل الحساب',
          'Export logs': 'تصدير السجلات',
          'To Do Lists': 'قوائم المهام',
          "Success is not just making money. Success is happiness. Success is fulfillment; it's the ability to give.":
              "النجاح ليس مجرد كسب المال. النجاح هو السعادة. النجاح هو الإنجاز؛ إنه القدرة على العطاء.",
          "Success isn't just about what you accomplish in your life; it's about what you inspire others to do.":
              "النجاح ليس فقط عن الإنجازات التي تحققها في حياتك؛ إنه عن ما تلهم الآخرين للقيام به.",
          "Success is peace of mind, which is a direct result of self-satisfaction in knowing you made the effort to become the best of which you are capable.":
              "النجاح هو سلام العقل، وهو نتيجة مباشرة للرضا الذاتي عن معرفة أنك بذلت جهدًا لتصبح أفضل ما يمكنك.",
          "The only thing standing between you and outrageous success is continuous progress.":
              "الشيء الوحيد الذي يقف بينك وبين النجاح المذهل هو التقدم المستمر.",
          "Don't let the fear of losing be greater than the excitement of winning.":
              "لا تدع خوف الخسارة يكون أكبر من حماس الفوز.",
          "Success is achieved and maintained by those who try and keep trying.":
              "يتحقق النجاح ويُحافظ عليه من قبل الذين يحاولون ويستمرون في المحاولة.",
          "Success is not final; failure is not fatal: It is the courage to continue that counts.":
              "النجاح ليس نهائيًا؛ الفشل ليس قاتلًا: إن الشجاعة للمضي قدمًا هي التي تحسب.",
          "Success does not consist in never making mistakes but in never making the same one a second time.":
              "النجاح لا يكمن في عدم ارتكاب الأخطاء ولكن في عدم ارتكاب نفس الخطأ مرة ثانية.",
          "The secret of success in life is for a man to be ready for his opportunity when it comes.":
              "سر النجاح في الحياة هو أن يكون الإنسان جاهزًا لفرصته عندما تأتي.",
          "The successful man will profit from his mistakes and try again in a different way.":
              "الرجل الناجح سيستفيد من أخطائه وسيحاول مرة أخرى بطريقة مختلفة.",
          "The Role Has Been Updated Successfully": "تم تحديث الدور بنجاح",
          "The foundation stones for a balanced success are honesty, character, integrity, faith, love and loyalty.":
              "أساسات النجاح المتوازنة هي الصدق والشخصية والنزاهة والإيمان والحب والولاء.",
          "Success is not to be pursued; it is to be attracted by the person you become.":
              "النجاح لا يسعى إليه؛ بل يُجذب إليه الشخص الذي تصبح عليه.",
          "Success is doing ordinary things extraordinarily well.":
              "النجاح هو أداء الأشياء العادية بشكل غير عادي بشكل متميز.",
          "Success is finding satisfaction in giving a little more than you take.":
              "النجاح هو إيجاد الرضا في إعطاء قليلاً أكثر مما تأخذ.",
          "Success is not the absence of problems; it is the ability to deal with them.":
              "النجاح ليس غياب المشاكل؛ إنه القدرة على التعامل معها.",
          "Success is never accidental.": "النجاح ليس أبدًا عرضيًا.",
          "Success is to be measured not so much by the position that one has reached in life as by the obstacles which he has overcome.":
              "يتم قياس النجاح ليس فقط بالمكان الذي وصل إليه الشخص في الحياة بقدر ما يتم قياسه بالعقبات التي تغلب عليها.",
          "The successful warrior is the average man, with laser-like focus.":
              "المحارب الناجح هو الرجل العادي، ذو التركيز الحاد.",
          "The only place where success comes before work is in the dictionary.":
              "المكان الوحيد الذي يأتي فيه النجاح قبل العمل هو في القاموس.",
          "Success seems to be connected with action. Successful people keep moving. They make mistakes but they don’t quit.":
              "يبدو أن النجاح مرتبط بالعمل. الأشخاص الناجحين يستمرون في التحرك. يرتكبون الأخطاء لكنهم لا يستسلمون.",
          "In order to succeed, your desire for success should be greater than your fear of failure.":
              "لكي تنجح، يجب أن تكون رغبتك في النجاح أكبر من خوفك من الفشل.",
          "Success is liking yourself, liking what you do, and liking how you do it.":
              "النجاح هو أن تحب نفسك، وتحب ما تفعل، وتحب كيف تفعله.",
          "Patience, persistence and perspiration make an unbeatable combination for success.":
              "الصبر والمثابرة والتعرق تجعلون مزيجاً لا يُقهر للنجاح.",
          "Perseverance is a great element of success. If you only knock long enough and loud enough at the gate, you are sure to wake up somebody.":
              "المثابرة هي عنصر كبير من النجاح. إذا طرقت بما فيه الكفاية وبصوت عالٍ عند البوابة، فمن المؤكد أنك ستوقظ شخصًا ما.",
          "Success is not built on success. It's built on failure. It's built on frustration. Sometimes it's built on catastrophe.":
              "النجاح لا يُبنى على النجاح. إنه يُبنى على الفشل. إنه يُبنى على الإحباط. أحيانًا يُبنى على الكارثة.",
          "Success means doing the best we can with what we have. Success is the doing, not the getting; in the trying, not the triumph.":
              "النجاح يعني القيام بأفضل ما لدينا باستخدام ما نملكه. النجاح هو الفعل، ليس الحصول؛ في المحاولة، ليس الانتصار.",
          "Success is how high you bounce when you hit bottom.":
              "النجاح هو مدى ارتفاعك عندما تصطدم بالقاع.",
          "Success is not about how much money you make, it's about the difference you make in people's lives.":
              "النجاح لا يتعلق بكم من المال تكسبه، إنه يتعلق بالفارق الذي تحدثه في حياة الناس.",
          "The secret of success is to do the common thing uncommonly well.":
              "سر النجاح هو أن تفعل الشيء العادي بشكل غير عادي جيدًا.",
          "Success is to wake up each morning and consciously decide that today will be the best day of your life.":
              "النجاح هو أن تستيقظ كل صباح وتقرر بوعي أن اليوم سيكون أفضل يوم في حياتك.",
          "The road to success and the road to failure are almost exactly the same.":
              "طريق النجاح وطريق الفشل تقريبًا هما نفس الشيء.",
          "Success is not the absence of failure; it's the persistence through failure.":
              "النجاح ليس غياب الفشل؛ إنه استمرارية خلال الفشل.",
          "Success is a journey, not a destination. The doing is often more important than the outcome.":
              "النجاح هو رحلة، ليس وجهة. الفعل غالبًا ما يكون أكثر أهمية من النتيجة.",
          "Success is a state of mind. If you want success, start thinking of yourself as a success.":
              "النجاح هو حالة نفسية. إذا كنت تريد النجاح، فابدأ بالتفكير في نفسك كناجح.",
          "You know you are on the road to success if you would do your job, and not be paid for it.":
              "تعرف أنك في طريق النجاح إذا كنت ستقوم بعملك، ولن تدفع مقابله.",
          "Hardships often prepare ordinary people for an extraordinary destiny.":
              "الصعاب غالباً ما تعد الأشخاص العاديين لمصير غير عادي.",
          "The only limit to our realization of tomorrow will be our doubts of today.":
              "الحد الوحيد لتحقيقنا للغد سيكون شكوكنا اليوم.",
          "Creativity is intelligence having fun.": "الإبداع هو الذكاء يستمتع.",
          "What you get by achieving your goals is not as important as what you become by achieving your goals.":
              "ما تحصل عليه من تحقيق أهدافك ليس بأهمية ما تصبح عليه من خلال تحقيق أهدافك.",
          "To see what is right and not do it is a lack of courage.":
              "رؤية ما هو صحيح وعدم فعله هو نقص في الشجاعة.",
          "Don't raise your voice, improve your argument.":
              "لا ترفع صوتك، حسن حجتك.",
          "Education is the most powerful weapon which you can use to change the world.":
              "التعليم هو السلاح الأقوى الذي يمكنك استخدامه لتغيير العالم.",
          "Start where you are. Use what you have. Do what you can.":
              "ابدأ من حيث أنت. استخدم ما لديك. افعل ما تستطيع.",
          "Do not wait to strike till the iron is hot, but make it hot by striking.":
              "لا تنتظر حتى يسخن الحديد، بل اجعله ساخناً بالضرب.",
          "The harder the conflict, the more glorious the triumph.":
              "كلما كان الصراع أصعب، كلما كان الانتصار أكثر مجداً.",
          "Keep your face always toward the sunshine—and shadows will fall behind you.":
              "احتفظ بوجهك دائماً نحو الشمس، وسيسقط الظلال خلفك.",
          "Success is not how high you have climbed, but how you make a positive difference to the world.":
              "النجاح ليس بمدى ارتفاعك، بل بكيفية قدرتك على إحداث فارق إيجابي في العالم.",
          "Your true success in life begins only when you make the commitment to become excellent at what you do.":
              "يبدأ نجاحك الحقيقي في الحياة فقط عندما تتعهد بأن تصبح متميزاً فيما تقوم به.",
          "Nothing in the world can take the place of Persistence. Talent will not; nothing is more common than unsuccessful men with talent.":
              "لا شيء في العالم يمكن أن يحل محل الثبات. لن يحل الموهبة؛ لا شيء أكثر شيوعًا من الرجال الفاشلين ذوي المواهب.",
          "The path to success is to take massive, determined action.":
              "الطريق إلى النجاح هو اتخاذ إجراءات ضخمة ومحددة.",
          "Never give up, for that is just the place and time that the tide will turn.":
              "لا تستسلم أبداً، لأن هذا هو المكان والوقت الذي سيتحول فيه المد.",
          "You just can’t beat the person who never gives up.":
              "لا يمكنك هزيمة الشخص الذي لا يستسلم أبداً.",
          "The difference between a successful person and others is not a lack of strength, not a lack of knowledge, but rather a lack in will.":
              "الفارق بين الشخص الناجح والآخرين ليس نقص في القوة، ولا نقص في المعرفة، ولكن النقص في الإرادة.",
          "Success usually comes to those who are too busy to be looking for it.":
              "النجاح عادة ما يأتي لأولئك الذين مشغولون جداً للبحث عنه.",
          "I find that the harder I work, the more luck I seem to have.":
              "أجد أن كلما عملت بجد، كلما زادت حظوظي.",
          "Don't be afraid to give up the good to go for the great.":
              "لا تخف من التخلي عن الممتاز من أجل الرائع.",
          "I attribute my success to this: I never gave or took any excuse.":
              "أرجع نجاحي إلى ذلك: لم أعط أو أتلق أي عذر.",
          "Success is not the key to happiness. Happiness is the key to success. If you love what you are doing, you will be successful.":
              "النجاح ليس مفتاح السعادة. السعادة هي مفتاح النجاح. إذا كنت تحب ما تفعله، ستكون ناجحاً.",
          "Success is not just about making money. It's about making a difference.":
              "النجاح ليس فقط عن كسب المال. إنه عن صنع فارق.",
          "The only way to do great work is to love what you do.":
              "الطريقة الوحيدة لعمل رائع هي أن تحب ما تفعله.",
          "Success is not the key to happiness. Happiness is the key to success.":
              "النجاح ليس مفتاح السعادة. السعادة هي مفتاح النجاح.",
          "Don't watch the clock; do what it does. Keep going.":
              "لا تنظر إلى الساعة؛ افعل ما تفعله. استمر.",
          "The future belongs to those who believe in the beauty of their dreams.":
              "المستقبل ينتمي إلى أولئك الذين يؤمنون بجمال أحلامهم.",
          "The best way to predict the future is to create it.":
              "أفضل طريقة للتنبؤ بالمستقبل هي صنعه.",
          "You miss 100% of the shots you don’t take.":
              "تفوت 100٪ من الفرص التي لا تأخذها.",
          "It always seems impossible until it’s done.":
              "يبدو دائمًا المستحيل حتى يتم تحقيقه.",
          "The harder you work for something, the greater you’ll feel when you achieve it.":
              "كلما عملت بجد لشيء ما، كلما شعرت بالسعادة الأكبر عند تحقيقه.",
          "Don’t stop when you’re tired. Stop when you’re done.":
              "لا تتوقف عندما تشعر بالتعب. توقف عندما تنتهي.",
          "Wake up with determination. Go to bed with satisfaction.":
              "استيقظ بتصميم. انام بالرضا.",
          "Do something today that your future self will thank you for.":
              "افعل شيئًا اليوم سيشكرك عليه نفسك في المستقبل.",
          "Little things make big days.": "الأشياء الصغيرة تجعل الأيام كبيرة.",
          "It’s going to be hard, but hard does not mean impossible.":
              "سيكون الأمر صعبًا، ولكن الصعوبة لا تعني المستحيل.",
          "Don’t wait for opportunity. Create it.": "لا تنتظر الفرصة، ابتكرها.",
          "Sometimes we’re tested not to show our weaknesses, but to discover our strengths.":
              "في بعض الأحيان نتم تجربة الاختبارات ليس لإظهار ضعفنا، ولكن لاكتشاف قوتنا.",
          "The key to success is to focus on goals, not obstacles.":
              "مفتاح النجاح هو التركيز على الأهداف، لا العقبات.",
          "Dream it. Wish it. Do it.": "حلم بذلك. تمنى بذلك. فعله.",
          "Success doesn’t just find you. You have to go out and get it.":
              "النجاح لا يأتي إليك فقط. عليك أن تخرج وتحصل عليه.",
          "The harder you work, the luckier you get.":
              "كلما عملت بجد، كلما زادت حظوظك.",
          "Good things come to people who wait, but better things come to those who go out and get them.":
              "الأشياء الجيدة تأتي لأولئك الذين ينتظرون، ولكن الأشياء الأفضل تأتي لأولئك الذين يخرجون ويحصلون عليها.",
          "Success is not in what you have, but who you are.":
              "النجاح ليس في ما تمتلك، بل في من تكون.",
          "To be the best, you must be able to handle the worst.":
              "لكي تكون الأفضل، يجب أن تتمكن من التعامل مع الأسوأ.",
          "Your limitation—it’s only your imagination.":
              "قيدك - إنها فقط خيالك.",
          "Push yourself, because no one else is going to do it for you.":
              "اسحب نفسك، لأنه لا أحد آخر سيفعل ذلك من أجلك.",
          "Great things never come from comfort zones.":
              "الأشياء العظيمة لا تأتي أبدًا من مناطق الراحة.",
          "Success is what happens after you have survived all your mistakes.":
              "النجاح هو ما يحدث بعد أن تقوم بالبقاء على قيد الحياة بجميع أخطائك.",
          "Don’t let yesterday take up too much of today.":
              "لا تدع الأمس يشغل كثيرًا من وقتك اليوم.",
          "If you are not willing to risk the usual, you will have to settle for the ordinary.":
              "إذا لم تكن على استعداد للمخاطرة بالمألوف، ستضطر إلى التسوية للعادي.",
          "Just when the caterpillar thought the world was over, it became a butterfly.":
              "فقط عندما يظن اليرقة أن العالم انتهى، تتحول إلى فراشة.",
