''': '''# شروط الخدمة لـ demo_app

من أجل تقديم خدماتنا (كما هو معرف أدناه) من خلال تطبيقاتنا وخدماتنا وميزاتنا وبرامجنا أو موقعنا الإلكتروني، نحتاج إلى الحصول على موافقتك على شروط الخدمة الخاصة بنا ("الشروط").

# حول خدماتنا
- مبادئ الخصوصية والأمان: منذ بدء demo_app، بنينا خدماتنا وفقًا لمبادئ قوية في مجال الخصوصية والأمان.
- ربطك بأشخاص آخرين: نوفر، ونسعى دائمًا لتحسين، طرقًا لك للتواصل مع مستخدمي demo_app الآخرين، بما في ذلك من خلال الرسائل والمكالمات الصوتية والفيديو، وإرسال الصور ومقاطع الفيديو، وعرض حالتك، ومشاركة موقعك مع الآخرين عندما تختار ذلك. يعمل demo_app مع شركاء ومزودي خدمات وشركات تابعة لمساعدتنا في توفير طرق لك للتواصل مع خدماتهم.
- طرق لتحسين خدماتنا: نحلل كيفية استخدامك لـ demo_app، من أجل تحسين خدماتنا، بما في ذلك مساعدة الشركات التي تستخدم demo_app في قياس فاعلية وتوزيع خدماتهم ورسائلهم. يستخدم demo_app المعلومات التي يملكها ويعمل أيضًا مع الشركاء ومزودي الخدمات والشركات التابعة لتحقيق ذلك.
- التواصل مع الشركات: نوفر، ونسعى دائمًا لتحسين، طرقًا لك وللشركات والمؤسسات الأخرى للتواصل مع بعضهما البعض باستخدام خدماتنا، مثل من خلال إشعارات، وتحديثات المنتجات والخدمات، والتسويق.
- السلامة والأمان والنزاهة: نعمل على حماية سلامة وأمان ونزاهة خدماتنا. وذلك يتضمن التعامل بشكل مناسب مع الأشخاص المسيئين والأنشطة المخالفة لشروطنا. نعمل على منع سوء استخدام خدماتنا، بما في ذلك السلوك الضار تجاه الآخرين وانتهاكات شروطنا وسياساتنا، ومعالجة الحالات التي يمكننا فيها مساعدة ودعم وحماية مجتمعنا. إذا تعلمنا عن وجود أشخاص أو أنشطة من هذا النوع، سنتخذ إجراءات مناسبة، بما في ذلك إزالة هؤلاء الأشخاص أو الأنشطة أو التواصل مع الجهات الأمنية. أي إزالة من هذا القبيل ستتم وفقًا لقسم "إنهاء" أدناه.
- تمكين الوصول إلى خدماتنا: لتشغيل خدماتنا العالمية، قد نحتاج إلى تخزين وتوزيع المحتوى والمعلومات في مراكز بيانات وأنظمة حول العالم، بما في ذلك خارج بلد إقامتك. استخدام هذه البنية التحتية العالمية ضروري وأساسي لتوفير خدماتنا. قد يكون هذه البنية التحتية مملوكة أو مشغلة من قبل مزودي الخدمة لدينا.
- إذا كنت مستخدمًا لـ demo_app ومقيمًا في الولايات المتحدة الأمريكية أو كندا، فإن شروطنا تحتوي على بند للتحكيم القانوني، والذي ينص على أن demo_app وأنت توافقان على حل جميع النزاعات (التي يتم تعريفها أدناه) من خلال التحكيم الفردي القانوني، ما لم تختار عدم المشاركة فيه وباستثناء بعض أنواع النزاعات. وهذا يعني أنك تتنازل عن أي حق لتحديد هذه النزاعات من قبل قاضي أو هيئة محلفين، وتتنازل عن حقك في المشاركة في دعاوى الفئات، أو التحكيم الجماعي، أو الدعاوى النموذجية. يرجى قراءة قسم "البند الخاص بالتحكيم القانوني لمستخدمي الولايات المتحدة الأمريكية أو كندا" أدناه لمعرفة المزيد.
- يجب عليك التسجيل في خدماتنا باستخدام معلومات دقيقة وتقديم رقم هاتفك المحمول الحالي، وإذا قمت بتغييره، فيجب عليك تحديث رقم هاتفك المحمول باستخدام ميزة تحرير الملف الشخصي المتوفرة في التطبيق. أنت توافق على استلام رسائل نصية ومكالمات هاتفية (منا أو من مقدمي الخدمة الخارجيين لدينا) تحتوي على رموز للتسجيل في خدماتنا إذا لزم الأمر.
- يجب أن تكون على الأقل 13 عامًا للتسجيل واستخدام خدماتنا (أو أن تكون الحد الأدنى للعمر المطلوب في بلدك أو إقليمك لتكون مؤهلاً للتسجيل واستخدام خدماتنا دون موافقة الوالدين). بالإضافة إلى أن تكون بالحد الأدنى المطلوب من العمر لاستخدام خدماتنا وفقًا للقوانين السارية، إذا لم تكن بما فيه الكفاية للحصول على السلطة اللازمة للموافقة على شروطنا في بلدك أو إقليمك، يجب أن يوافق والدك أو وصيك على شروطنا نيابةً عنك. يرجى طلب من والدك أو وصيك قراءة هذه الشروط معك.
- يجب عليك توفير بعض الأجهزة والبرامج واتصالات البيانات لاستخدام خدماتنا، والتي لا نوفرها بشكل آخر. من أجل استخدام خدماتنا، فإنك توافق على تنزيل التحديثات الخاصة بخدماتنا يدويًا أو تلقائيًا وتثبيتها. كما توافق على أن نرسل لك إشعارات من خلال خدماتنا من وقت لآخر، حسب الضرورة لتوفير خدماتنا لك.
- أنت مسؤول عن جميع خطط بيانات الناقل ورسوم الإنترنت والرسوم الأخرى والضرائب المرتبطة باستخدامك لخدماتنا.

# سياسة الخصوصية وبيانات المستخدم

تهتم demo_app بخصوصيتك. تصف سياسة الخصوصية لـ demo_app بياناتنا (بما في ذلك الرسائل) وممارساتنا، بما في ذلك أنواع المعلومات التي نتلقاها ونجمعها منك، وكيفية استخدامنا ومشاركتنا لهذه المعلومات، وحقوقك المتعلقة بمعالجة المعلومات المتعلقة بك.

# الاستخدام المقبول لخدماتنا

- يجب عليك استخدام خدماتنا وفقًا لشروطنا والسياسات المنشورة. إذا انتهكت شروطنا أو سياساتنا، فقد نتخذ إجراءات تجاه حسابك، بما في ذلك تعطيل أو تعليق حسابك، وإذا قمنا بذلك، فإنك توافق على عدم إنشاء حساب آخر بدون إذننا. سيتم تعطيل أو تعليق حسابك وفقًا لقسم "الإنهاء" أدناه.

- يجب عليك الوصول إلى خدماتنا واستخدامها فقط لأغراض قانونية ومصرح بها ومقبولة. لن تستخدم (أو تساعد الآخرين في استخدام) خدماتنا بطرق تنتهك أو تستولي على حقوق demo_app أو مستخدمينا أو الآخرين، بما في ذلك حقوق الخصوصية والشهرة والملكية الفكرية أو حقوق الملكية الأخرى.

   **أ)** تكون غير قانونية، مبتذلة، مُجدرة للكراهية، تهديدية، مزعجة، كارهة، مسيئة عنصريًا أو عرقيًا، أو تحرض أو تشجع على سلوك غير قانوني أو غير مناسب بأي شكل من الأشكال، مثل تعزيز الجرائم العنيفة أو تعريض الأطفال أو الآخرين للخطر أو استغلالهم، أو تنسيق الضرر

   **ب)** تكون غير قانونية، مشينة، مجدرة للكراهية، مسيئة، تهديدية، تخويفية، كارهة، عنصرية أو تعرقية، أو تحرض أو تشجع على سلوك يعتبر غير قانوني أو غير مناسب بأي شكل من الأشكال، مثل الترويج لجرائم عنيفة، تعريض الأطفال أو الآخرين للخطر أو استغلالهم، أو تنسيق الضرر.

   **ج)** تنطوي على نشر أكاذيب أو تحريف الحقائق أو إصدار بيانات مضللة.

   **د)** التنكر في شخص آخر.

   **هـ)** تنطوي على إرسال رسائل غير قانونية أو غير مسموح بها مثل الرسائل الجماعية، والرسائل التلقائية، والاتصال التلقائي وما شابه ذلك.

   **و)** تنطوي على أي استخدام غير شخصي لخدماتنا ما لم يكن مصرحًا به غير ذلك من قبلنا.

- يجب عليك عدم (أو مساعدة الآخرين في ذلك) بشكل مباشر أو غير مباشر، عن طريق وسائل آلية أو غيرها، الوصول إلى خدماتنا، أو استخدامها، أو نسخها، أو تكييفها، أو تعديلها، أو إعداد أعمال مشتقة بناءً عليها، أو توزيعها، أو منح ترخيص لها، أو إعطاء ترخيص فرعي لها، أو نقلها، أو عرضها، أو تنفيذها، أو استغلالها بأي طريقة غير مشروعة أو غير مصرح بها، أو بطرق تثقلنا، أو تضرنا، أو تؤذي خدماتنا، أو أنظمتنا، أو مستخدمينا، أو الآخرين، بما في ذلك يجب عليك عدم القيام بما يلي بشكل مباشر أو عن طريق وسائل آلية:

  **أ)** إعادة هندسة عكسية، أو تغيير، أو تعديل، أو إنشاء أعمال مشتقة، أو فك تشفير، أو استخلاص الشفرة من خدماتنا؛

  **ب)** إرسال، أو تخزين، أو نقل الفيروسات أو أي برامج ضارة أخرى عبر خدماتنا؛

  **ج)** الحصول على الوصول غير المصرح به أو محاولة الحصول على الوصول غير المصرح به إلى خدماتنا أو أنظمتنا؛

  **د)** التدخل في سلامة، وأمان، وسرية، ونزاهة، وتوفر، وأداء خدماتنا؛

  **هـ)** إنشاء حسابات لخدماتنا عبر وسائل غير مصرح بها أو وسائل آلية؛

  **و)** جمع معلومات عن مستخدمينا أو عنهم بأي طريقة غير مشروعة أو غير مصرح بها؛

  **ز)** بيع، أو إعادة بيع، أو تأجير، أو فرض رسوم على خدماتنا أو البيانات التي تم الحصول عليها منا أو من خدماتنا بطرق غير مصرح بها؛

  **ح)** توزيع أو توفير خدماتنا عبر شبكة يمكن استخدامها من قبل أجهزة متعددة في نفس الوقت، ما لم يتم ذلك بالطرق المصرح بها من خلال الأدوات التي قدمناها بشكل صريح عبر خدماتنا؛

  **ط)** إنشاء برامج أو واجهات برمجة تعمل بشكل مشابه لخدماتنا وتقدمها للاستخدام من قبل أطراف ثالثة بطرق غير مصرح بها؛

  **ي)** إساءة استخدام أي قنوات للإبلاغ، مثل تقديم تقارير أو استئنافات زائفة أو بدون أساس.

- أنت مسؤول عن الحفاظ على جهازك وحسابك على "demo_app" آمنين ومحميين، ويجب عليك إبلاغنا على الفور بأي استخدام غير مصرح به أو انتهاك أمان لحسابك أو خدماتنا.

# خدمات الأطراف الثالثة

قد تتيح لك خدماتنا الوصول إلى مواقع الويب وتطبيقات الأطراف الثالثة والمحتوى والمنتجات والخدمات الأخرى. يرجى ملاحظة أن هذه الشروط وسياسة الخصوصية تنطبق فقط على استخدام خدماتنا. عند استخدام منتجات أو خدمات الأطراف الثالثة، ستسري شروطهم وسياسات الخصوصية على استخدامك لتلك المنتجات أو الخدمات.

# التراخيص
- لا تدعي demo_app ملكية المعلومات التي تقدمها لحساب demo_app الخاص بك أو من خلال خدماتنا. يجب أن تكون لديك الحقوق اللازمة في هذه المعلومات التي تقدمها لحساب demo_app الخاص بك أو من خلال خدماتنا، ويجب أن تكون لديك الحق في منح الحقوق والتراخيص وفقًا لشروطنا.

- نحن نمتلك جميع حقوق النشر والعلامات التجارية والنطاقات والشعارات والشكل التجاري وأسرار الصناعة وبراءات الاختراع وحقوق الملكية الفكرية الأخرى المرتبطة بخدماتنا. لا يجوز لك استخدام حقوق النشر لدينا أو العلامات التجارية (أو أي علامات مماثلة) أو النطاقات أو الشعارات أو الشكل التجاري أو أسرار الصناعة أو براءات الاختراع أو حقوق الملكية الفكرية الأخرى ما لم تحصل على إذن صريح منا وبموجب إرشادات العلامة التجارية لدينا. يجوز لك استخدام علامات التجارية التابعة لشركاتنا التابعة فقط بإذنها، بما في ذلك الاستخدام المصرح به في أي إرشادات علامة تجارية منشورة.

- من أجل تشغيل وتوفير خدماتنا، فإنك تمنح demo_app ترخيصًا عالميًا وغير حصري وخاليًا من الروابط وقابلًا للترخيص الفرعي وقابلًا للنقل لاستخدام واستنساخ وتوزيع وإنشاء أعمال مشتقة من وعرض وأداء المعلومات (بما في ذلك المحتوى) الذي تقوم بتحميله أو تقديمه أو تخزينه أو إرساله أو استلامه على خدماتنا. الحقوق التي تمنحها في هذا الترخيص هي للغرض المحدود من تشغيل وتوفير خدماتنا (مثل السماح لنا بعرض صورة ملف تعريفك ونقل رسائلك وتخزين رسائلك غير المستلمة على خوادمنا لمدة تصل إلى 30 يومًا أثناء محاولتنا توصيلها).

- نحن نمنحك ترخيصًا محدودًا وقابلًا للإلغاء وغير حصري وغير قابل للترخيص الفرعي وغير قابل للنقل لاستخدام خدماتنا، وفقًا لشروطنا ووفقًا لها. هذا الترخيص هو للغرض الوحيد من تمكينك من استخدام خدماتنا بالطريقة المسموح بها في شروطنا. لا يتم منحك تراخيص أو حقوق ضمنيًا أو بأي طريقة أخرى، ما لم يتم منحك تراخيص وحقوق صراحة.
# الإبلاغ عن انتهاك حقوق الملكية الفكرية للأطراف الثالثة

للإبلاغ عن ادعاءات انتهاك حقوق الملكية الفكرية للأطراف الثالثة، يرجى زيارة سياسة الملكية الفكرية الخاصة بنا. قد نتخذ إجراءات تجاه حسابك، بما في ذلك تعطيله أو إيقافه، إذا كنت تنتهك بوضوح أو بشكل جاد أو متكرر حقوق الملكية الفكرية للآخرين أو إذا كانت هناك ضرورة قانونية لذلك. ستتم عملية تعطيل أو إيقاف حسابك وفقًا لقسم "إنهاء الخدمة" الموضح أدناه.

# الإخلاء والتنازلات

تستخدم خدماتنا على مسؤوليتك الشخصية ووفقًا للإخلاءات التالية:
- نحن نقدم خدماتنا على أساس "كما هي" دون أي ضمانات صريحة أو ضمنية، بما في ذلك ولكن لا تقتصر على ضمانات التسويقية، واللياقة لغرض معين، والعنوان، وعدم الانتهاك، والحماية من الفيروسات الكمبيوترية أو أي برامج ضارة أخرى.
- نحن لا نضمن أن أي معلومات تقدمها لنا هي دقيقة أو كاملة أو مفيدة، وأن خدماتنا ستكون تشغيلية وخالية من الأخطاء وآمنة، وأن خدماتنا ستعمل بدون انقطاعات أو تأخيرات أو عيوب.
- نحن لا نسيطر، ولا نتحمل مسؤولية السيطرة على كيفية استخدام المستخدمين لخدماتنا أو الميزات أو الخدمات أو الواجهات التي توفرها خدماتنا.
- نحن غير مسؤولين عن أعمال المستخدمين أو المعلومات (بما في ذلك المحتوى) ولا نلتزم بالسيطرة عليها، سواء كانوا مستخدمين لدينا أو أطرافًا ثالثة أخرى.
- تُعفينا، وشركاتنا التابعة، وشركاءنا، ومدراءنا، وموظفينا، وشركاءنا، ووكلائنا (معًا، "أطراف demo_app") من أي ادعاء، شكوى، سبب من الأسباب، نزاع، نزاع، أو أضرار (معًا "المطالبة")، معروفة أو غير معروفة، تتعلق بالمطالبة التي لديك ضد أي أطراف ثالثة.
- لا يتم تعديل حقوقك فيما يتعلق بأطراف demo_app بسبب الإخلاء المذكور أعلاه إذا لم تسمح به القوانين في بلدك أو إقليم إقامتك وفقًا لاستخدامك لخدماتنا.
- إذا كنت مقيمًا في الولايات المتحدة الأمريكية، فإنك تتنازل عن أي حقوق قد تكون لديك بموجب القانون المدني لولاية كاليفورنيا §1542، أو أي قانون مماثل آخر ينطبق في أي اختصاص قضائي آخر، والذي ينص على أن الإخلاء العام لا يمتد إلى المطالبات التي لا يعلم الدائن أو الطرف المفرج عنه وجودها، أو يشتبه في وجودها، لصالحه في وقت تنفيذ الإخلاء، وإذا كانت معروفة لديه، لكانت لها تأثير مهم على تسويته مع الدائن أو الطرف المفرج عنه.

# قيود المسؤولية

- لن تكون أطراف demo_app مسؤولة تجاهك عن أي أرباح مفقودة أو أضرار تبعية أو عقابية أو غير مباشرة أو طارئة تتعلق بالشروط الخاصة بنا أو بنا أو بخدماتنا (بغض النظر عن السبب وعلى أي نظرية للمسؤولية، بما في ذلك الإهمال)، حتى لو كانت أطراف demo_app قد تلقت تنبيهًا بإمكانية وجود مثل هذه الأضرار. لن تتجاوز المسؤولية الإجمالية لدينا المتعلقة بالشروط الخاصة بنا أو بنا أو بخدماتنا أكثر من مائة دولار (1) أو المبلغ الذي دفعته لنا خلال الاثني عشر شهرًا الماضية، وذلك حسب الحد الأعلى المسموح به بموجب القانون المعمول به. سينطبق الإخلاء المذكور لبعض الأضرار وتقييد المسؤولية إلى أقصى حد مسموح به بموجب القانون المعمول به. قد لا تسمح قوانين بعض الولايات أو الاختصاصات بإستبعاد أو تقييد بعض الأضرار المعينة، لذا قد لا تنطبق بعض أو كل من الاستبعادات والتقييدات المذكورة أعلاه عليك. على الرغم من أي شيء يتعارض مع ذلك في الشروط الخاصة بنا، في مثل هذه الحالات، ستكون مسؤولية أطراف demo_app محدودة إلى أقصى حد يسمح به القانون المعمول به.

# التعويض

- إذا قدم أي شخص ادعاءً ("ادعاء طرف ثالث") ضدنا يتعلق بأفعالك أو معلوماتك أو محتوى على "demo_app"، أو أي استخدام آخر لخدماتنا من قِبلك، ستكون مسؤولاً عن تعويض الأطراف المعنية في أقصى حد مسموح به بموجب القانون المعمول به، وتعفي الأطراف المعنية من أي التزامات قانونية أو أضرار أو خسائر أو مصروفات من أي نوع (بما في ذلك الرسوم القانونية والتكاليف المعقولة) المتعلقة بأو تنشأ عن أو تتصل بأي من ما يلي:

  **أ)** الوصول الخاص بك أو استخدامك لخدماتنا، بما في ذلك المعلومات والمحتوى المقدم فيما يتصل بذلك؛

  **ب)** انتهاكك لشروطنا أو القانون المعمول به؛

  **ج)** أي تضليل تقوم به.
ستتعاون بشكل كامل حسبما يُطلب منك من قِبلنا في الدفاع عن أو تسوية أي ادعاءٍ من جانب أطراف ثالثة. لا يتم تعديل حقوقك فيما يتعلق بـ "demo_app" من خلال التعويض المذكور أعلاه إذا لم يسمح بها قانون بلدك أو إقليم إقامتك، وذلك نتيجة استخدامك لخدماتنا.

# تسوية المنازعات

- إذا كنت مستخدمًا لـ "demo_app" موجودًا في الولايات المتحدة أو كندا، فإن قسم "أحكام التحكيم الخاصة بمستخدمي الولايات المتحدة أو كندا" أدناه ينطبق عليك. يرجى قراءة هذا القسم أيضًا بعناية وبالكامل. إذا لم تكن تخضع لقسم "أحكام التحكيم الخاصة بمستخدمي الولايات المتحدة أو كندا" أدناه، فإنك توافق على أن أي ادعاء أو سبب قانوني لديك ضد "demo_app" المتعلق بشروطنا أو خدماتنا، وأي ادعاء أو سبب قانوني يقدمه "demo_app" ضدك، يتم التوصل إلى اتفاق بينك وبين "demo_app" بأن أي مثل هذا الادعاء أو سبب قانوني (كل منها "نزاع"، ومعًا "نزاعات") سيتم حله بشكل حصري في محكمة الولايات المتحدة الأمريكية في منطقة الولايات المتحدة الشمالية في كاليفورنيا أو محكمة ولاية سان ماتيو في مقاطعة كاليفورنيا، وتوافق على التقدم بالنزاع لاختصاص هذه المحاكم الشخصية لمنازعة أي مثل هذا الادعاء أو سبب قانوني، وتشمل قوانين ولاية كاليفورنيا أي مثل هذا الادعاء أو سبب قانوني دون النظر إلى أحكام تعارض القوانين. دون المساس بما سبق، فإنك توافق على أنه بناءً على تقديرنا الخاص، قد نختار حل أي نزاع لدينا معك الذي لا يخضع للتحكيم في أي محكمة مختصة في البلد الذي تقيم فيه والذي يحظى بالاختصاص على النزاع.
- قوانين جمهورية مصر العربية تحكم شروطنا، فضلاً عن أي نزاعات، سواء في المحكمة أو التحكيم، التي قد تنشأ بين "demo_app" وبينك، دون النظر إلى أحكام تعارض القوانين.
- تحدد هذه الشروط أيضًا الوقت المتاح لديك لتقديم ادعاء أو نزاع، بما في ذلك الوقت المتاح لبدء التحكيم أو، إذا سمحت القوانين، إجراء قضائي أو إجراءات المطالبات الصغيرة، إلى أقصى حد مسموح به بموجب القانون المعمول به. نحن وأنت نتفق على أنه بالنسبة لأي نزاع (باستثناء النزاعات المستبعدة المعرفة أدناه) يجب علينا أن نقدم الادعاءات (بما في ذلك بدء إجراء التحكيم) في غضون شهر واحد بعد تنشأ النزاع للمرة الأولى؛ وإلا، يُعتبر مثل هذا النزاع محظورًا بشكل دائم. وهذا يعني أنه إذا لم نقدم أي من الطرفين (بما في ذلك بدء التحكيم) في غضون شهر واحد بعد تنشأ النزاع للمرة الأولى، فإن التحكيم سيتم إلغاؤه لأنه بدأ في وقت متأخر جدًا. انظر أدناه: أحكام التحكيم الخاصة بمستخدمي الولايات المتحدة أو كندا.

# توافر الخدمات وإنهاؤها

- نحن نسعى دائمًا لتحسين خدماتنا. وهذا يعني أنه قد نقوم بتوسيع خدماتنا، أو إضافة خصائص ووظائف جديدة، أو إزالة بعض الخدمات، ودعم بعض الأجهزة والمنصات. قد يتم انقطاع خدماتنا، بما في ذلك لأعمال الصيانة، أو الإصلاحات، أو الترقيات، أو فشل الشبكة أو الأجهزة. قد نقوم بإنهاء بعض أو كل خدماتنا، بما في ذلك بعض الميزات ودعم بعض الأجهزة والمنصات، في أي وقت. قد تؤثر الأحداث التي تكون خارجة عن سيطرتنا على خدماتنا، مثل الأحداث الطبيعية والأحداث القاهرة الأخرى.
- على الرغم من أننا نأمل أن تظل مستخدمًا لـ "demo_app"، يمكنك إنهاء علاقتك مع "demo_app" في أي وقت ولأي سبب عن طريق حذف حسابك. للحصول على تعليمات حول كيفية القيام بذلك، يرجى زيارة المقالات المتعلقة بنظام Android و iPhone في مركز المساعدة لدينا.

- يمكننا تعديل أو تعليق أو إنهاء وصولك إلى خدماتنا أو استخدامها في أي وقت ولأي سبب، مثل في حالة خرقك لحروف أو مضمون 
شروطنا أو خلق الضرر أو المخاطرة أو تعريضنا للمسائل القانونية المحتملة، أو تعريض مستخدمينا أو الآخرين للخطر.

# البنود الأخرى

- ما لم يتم تنفيذ اتفاق مشترك بينك وبينا ينص على خلاف ذلك، فإن شروطنا تشكل المطلقة للاتفاق بينك وبينا بشأن demo_app وخدماتنا وتحل محل أي اتفاقات سابقة.
- نحتفظ بالحق في تحديد في المستقبل أن بعض خدماتنا تخضع لشروط منفصلة (حيث يمكنك أن توافق بشكل منفصل في الحالات المناسبة).
- لا تهدف خدماتنا للتوزيع أو الاستخدام في أي بلد أو إقليم ينتهك فيه هذا التوزيع أو الاستخدام القانون المحلي أو يعرضنا لأي تنظيمات في بلد أو إقليم آخر. نحتفظ بالحق في تقييد خدماتنا في أي بلد أو إقليم.


- ستلتزم بجميع قوانين السيطرة على التصدير والعقوبات التجارية المعمول بها في الولايات المتحدة وغير الولايات المتحدة ("قوانين التصدير"). لن تصدر أو تعيد تصدير خدماتنا بشكل مباشر أو غير مباشر أو توفرها أو تنقلها بأي طريقة أخرى:

    **أ)** إلى أي فرد أو كيان أو إقليم أو بلد محظور بموجب قوانين التصدير؛

    **ب)** لأي شخص مدرج في قوائم الأطراف المحظورة من قبل الحكومة الأمريكية أو غير الأمريكية؛

    **ج)** لأي غرض محظور بموجب قوانين التصدير، بما في ذلك الأسلحة النووية أو الكيماوية أو البيولوجية، أو تطبيقات تكنولوجيا الصواريخ بدون تراخيص الحكومة المطلوبة. لن تستخدم أو تقوم بتنزيل خدماتنا إذا كنت موجودًا في بلد أو منطقة محظورة، إذا كنت مدرجًا حاليًا في أي قوائم الأطراف المحظورة للولايات المتحدة أو غير الأمريكية، أو لأي غرض محظور بموجب قوانين التصدير، ولن تقم بإخفاء موقعك عن طريق وكالة IP الخاصة بك أو بطرق أخرى.

- شروطنا مكتوبة باللغة الإنجليزية (الولايات المتحدة). أي نسخة مترجمة مقدمة هنا تُقدم فقط لراحتك. في حالة تعارض أي نسخة مترجمة من شروطنا مع النسخة الإنجليزية، تكون النسخة الإنجليزية هي الصحيحة. أي تعديل أو تنازل مقترح منك بشأن شروطنا يتطلب موافقتنا الصريحة.
- قد نقوم بتعديل أو تحديث هذه الشروط. سنقوم بإعلامك بأي تعديلات مهمة على شروطنا، حسب الاقتضاء، وسنقوم بتحديث تاريخ "آخر تعديل" في أعلى الشروط. استخدامك المستمر لخدماتنا يؤكد قبولك لشروطنا، بعد التعديلات. نأمل أن تستمر في استخدام خدماتنا، ولكن إذا لم توافق على شروطنا، بعد التعديلات، يجب عليك التوقف عن استخدام خدماتنا عن طريق حذف حسابك.
- جميع حقوقنا والتزاماتنا بموجب شروطنا يمكننا نقلها بحرية إلى أي من الشركات التابعة لنا أو فيما يتعلق بعملية دمج، استحواذ، إعادة هيكلة، بيع أصول، أو بموجب القانون أو غير ذلك، ويمكننا نقل معلوماتك إلى أي من الشركات التابعة لنا أو الجهات الفاعلة الخاصة بالاستحواذ أو الشركة الجديدة. في حالة مثل هذا التعيين، ستظل هذه الشروط تحكم علاقتك مع هذه الجهة الثالثة. نأمل أن تستمر في استخدام خدماتنا، ولكن إذا لم توافق على مثل هذا التعيين، يجب عليك التوقف عن استخدام خدماتنا عن طريق حذف حسابك بعد أن يتم إخطارك بالتعيين.
- جميع حقوقنا والتزاماتنا بموجب شروطنا يمكننا نقلها بحرية إلى أي من الشركات التابعة لنا أو فيما يتعلق بعملية دمج، استحواذ، إعادة هيكلة، بيع أصول، أو بموجب القانون أو غير ذلك، ويمكننا نقل معلوماتك إلى أي من الشركات التابعة لنا أو الجهات الفاعلة الخاصة بالاستحواذ أو الشركة الجديدة. في حالة مثل هذا التعيين، ستظل هذه الشروط تحكم علاقتك مع هذه الجهة الثالثة. نأمل أن تستمر في استخدام خدماتنا، ولكن إذا لم توافق على مثل هذا التعيين، يجب عليك التوقف عن استخدام خدماتنا عن طريق حذف حسابك بعد أن يتم إخطارك بالتعيين.
- لن تقوم بنقل أي من حقوقك أو التزاماتك بموجب شروطنا إلى أي شخص آخر بدون موافقتنا الكتابية المسبقة.
- لا شيء في شروطنا سيمنعنا من الامتثال للقانون.
- باستثناء ما هو محدد هنا، فإن شروطنا لا تمنح أي حقوق للأطراف الثالثة كمستفيدين.
- إذا فشلنا في تنفيذ أي من شروطنا، فلن يعتبر ذلك تنازلاً عنه.
- إذا تبين أن أي بند في هذه الشروط غير قانوني أو غير صالح أو لأي سبب غير قابل للتنفيذ، فإنه يعتبر تعديلاً بحيث يتم جعله قابلاً للتنفيذ على أقل مدى ضروري، وإذا كان لا يمكن جعله قابلاً للتنفيذ، فإنه يعتبر قابلاً للفصل عن شروطنا ولا يؤثر على صحة وقابلية التنفيذ لبقية بنود شروطنا، ويظل الجزء الباقي من شروطنا ساري المفعول بكامله ما لم ينص خلاف ذلك في قسم "بند التحكيم الخاص للمستخدمين في الولايات المتحدة الأمريكية أو كندا" أدناه.
- نحتفظ بجميع الحقوق التي لم نمنحها صراحة لك. في بعض الولايات، قد يكون لديك حقوق قانونية كمستهلك، ولا تهدف شروطنا إلى تقييد تلك الحقوق القانونية للمستهلك التي قد لا يمكن الاستغناء عنها بواسطة العقد.
- نقدر دائمًا تعليقاتك واقتراحاتك الأخرى بشأن demo_app وخدماتنا، ولكنك تدرك أنه ليس عليك أي التزام بتقديم التعليقات أو الاقتراحات وأنه يمكننا استخدام تلك التعليقات أو الاقتراحات من دون أي قيد أو التزام بتعويضك عنها.

# بند التحكيم الخاص للمستخدمين في الولايات المتحدة الأمريكية أو كندا

يرجى قراءة هذا البند بعناية لأنه يحتوي على بنود إضافية تطبق فقط على مستخدمينا في الولايات المتحدة الأمريكية أو كندا. إذا كنت مستخدمًا لـ demo_app موجودًا في الولايات المتحدة الأمريكية أو كندا، فإنك ونحن نوافق على تقديم جميع النزاعات للتحكيم الفردي الرابط، باستثناء النزاعات التي تتعلق بحقوق الملكية الفكرية وباستثناء تلك التي يمكن تقديمها للمحكمة للدعاوى الصغيرة. وهذا يعني أنك تتنازل عن حقك في حل مثل تلك النزاعات في المحكمة أمام قاضٍ أو هيئة محلفين. وأخيرًا، يمكنك تقديم مطالبة فقط نيابة عن نفسك، وليس نيابة عن أي مسؤول رسمي آخر أو شخص آخر، أو فئة من الأشخاص. تتنازل عن حقك في المشاركة في النزاع أو أن يُعرف النزاع الخاص بك ويتم حله على أنه دعوى جماعية، أو تحكيم جماعي، أو دعوى تمثيلية.
"النزاع المستبعد" يعني أي نزاع يتعلق بتنفيذ أو انتهاك حقوق الملكية الفكرية الخاصة بك أو بنا (مثل حقوق النشر والعلامات التجارية والنطاقات والشعارات والزي التجاري وأسرار التجارة والبراءات) أو الجهود المبذولة للتدخل في خدماتنا أو التعامل مع خدماتنا بطرق غير مصرح بها (على سبيل المثال، بالطرق الآلية). للوضوح وبغض النظر عن ما سبق، فإن تلك النزاعات المتعلقة بحقوق الخصوصية والشهرة الخاصة بك ليست نزاعات مستبعدة.

قانون التحكيم الفدرالي: يحكم قانون التحكيم الفدرالي الأمريكي تفسير وتنفيذ بند "التحكيم الخاص للمستخدمين في الولايات المتحدة الأمريكية أو كندا" هذا، بما في ذلك أي مسألة تتعلق بما إذا كان النزاع بين demo_app وبينك يخضع للتحكيم.

اتفاقية التحكيم لمستخدمي demo_app الموجودين في الولايات المتحدة الأمريكية أو كندا: بالنسبة لمستخدمي demo_app الذين يعيشون في الولايات المتحدة الأمريكية أو كندا، يتفق demo_app وأنت على تنازلكما عن الحق في المحاكمة أمام قاضٍ أو هيئة محلفين في جميع النزاعات، باستثناء النزاعات المستبعدة. يتفق demo_app وأنت على أن جميع النزاعات (باستثناء النزاعات المستبعدة)، بما في ذلك تلك التي تتعلق بحقوق الخصوصية والشهرة الخاصة بك، ستُحل عن طريق التحكيم النهائي والملزم. يتفق demo_app وأنت على عدم دمج نزاع يخضع للتحكيم بموجب شروطنا مع نزاع غير مؤهل للتحكيم بموجب شروطنا. قبل أن تبدأ في التحكيم لنزاع، يجب عليك تقديم إشعار خطي للنزاع إلينا يتضمن (أ) اسمك؛ (ب) عنوان سكنك؛ (ج) اسم المستخدم؛ (د) عنوان البريد الإلكتروني أو رقم الهاتف الذي تستخدمه لحسابك في demo_app؛ (هـ) وصف مفصل للنزاع؛ و (ف) التسوية التي تطلبها. يجب أن يتم إرسال أي إشعار للنزاع ترسله إلينا عبر البريد الإلكتروني إلى support@demo_app.com. قبل أن نبدأ في التحكيم، سنرسل لك إشعارًا بالنزاع إلى عنوان البريد الإلكتروني الذي تقدمه، أو بوسائل مناسبة أخرى. إذا لم نتمكن من حل النزاع خلال ستين (90) يومًا بعد استلام إشعار النزاع، يجوز لك أو لنا أن نبدأ في التحكيم.

سيتم إدارة التحكيم من قبل الجمعية الأمريكية للتحكيم ("AAA") بموجب قواعد التحكيم التجاري الخاصة بها سارية المفعول في وقت بدء التحكيم، بما في ذلك القواعد الاختيارية لإجراءات الطوارئ للحماية والإجراءات الإضافية للنزاعات ذات الصلة بالمستهلك (المعروفة مجتمعة بـ "قواعد AAA"). سيترأس التحكيم محكم واحد يتم اختياره وفقًا لقواعد AAA. تتوفر قواعد AAA ومعلومات حول بدء نزاع ووصف لعملية التحكيم على الموقع التالي: www.adr.org. يُعتبر القضايا المتعلقة بنطاق وقابلية تنفيذ بند التحكيم مسؤولية المحكمة لاتخاذ قرار بشأنها. سيتم تحديد موقع التحكيم وتوزيع الرسوم والتكاليف المتعلقة بالتحكيم وفقًا لقواعد AAA.

إجراء إلغاء الاشتراك: يمكنك إلغاء الاشتراك في هذه الاتفاقية للتحكيم. إذا قمت بذلك، فلن يكون بإمكاننا أو بإمكانك أن نطالب الطرف الآخر بالمشاركة في إجراء التحكيم. لإلغاء الاشتراك، يجب عليك إخطارنا بذلك بكتابة وتسجيل البريد الخاص بك في غضون 60 يومًا من أحد التواريخ التالية: (أ) تاريخ قبولك لأول مرة لشروطنا؛ و (ب) تاريخ تعرضك لبند التحكيم هذا. يجب عليك استخدام عنوان البريد الإلكتروني التالي لإلغاء الاشتراك: support@demo_app.com

يجب أن تتضمن الرسالة: (أ) اسمك وعنوان إقامتك؛ (ب) رقم الهاتف المحمول المرتبط بحسابك؛ و (ج) بيان واضح بأنك ترغب في إلغاء الاشتراك في اتفاقية التحكيم الخاصة بشروطنا. محكمة الدعاوى الصغيرة. كبديل للتحكيم، وإذا سمحت به قواعد "محكمة الدعاوى الصغيرة" المحلية الخاصة بك، يمكنك إحالة النزاع إلى "محكمة الدعاوى الصغيرة" المحلية الخاصة بك، طالما أن المسألة تتقدم على أساس فردي (غير جماعي).
