* أضف صورة إلى ملف تعريفك يمكن أن تكون صورتك الشخصية أو شعار شركتك لمساعدة اتصالاتك على التعرف على حسابك.
# شارك بطاقات العمل الخاصة بك مع أي شخص
* يمكنك مشاركة بطاقة العمل الرقمية الخاصة بك مع أي شخص، حتى إن لم يكن لديه تطبيق demo_app، عن طريق إرسالهم رسائل نصية ودعوات بالبريد الإلكتروني.
* مع demo_app، يمكنك مشاركة جميع حساباتك وملفاتك الشخصية على وسائل التواصل الاجتماعي من مكان واحد.
* شارك بطاقة demo_app الخاصة بك باستخدام رمز الاستجابة السريعة الفريد QR code الخاص بك.


# إدارة جهات الاتصال الخاصة بك باستخدام دليل العناوين المحدث دائمًا
* demo_app هو نظام إدارة العلاقات الشخصية والمهنية المجاني الخاص بك. دليل العناوين الخاص بك يتم تحديثه دائمًا عندما يقوم المستخدمون بتعديل معلوماتهم.
*  للمستخدمين اختيار طريقة الاتصال المفضلة لديهم (رسائل نصية - مكالمات - بريد إلكتروني) ومشاركتها مع اتصالاتهم و جميع المستخدمين.

